//go:build amd64 && !purego

package serpent

// The vector kernels are generated by internal/genavx2 with go-asmgen, from
// the S-box expressions of sbox.go (AVX2, serpent_avx2_amd64.s) and Botan's
// ternary-logic tables (AVX-512, serpent_avx512_amd64.s). They process whole
// chunks of blocks; n is the number of chunks (see generate.go).

//go:noescape
func encryptBlocksAVX2x8(rk *uint32, dst, src *byte, n int)

//go:noescape
func decryptBlocksAVX2x8(rk *uint32, dst, src *byte, n int)

//go:noescape
func encryptBlocksAVX2x16(rk *uint32, dst, src *byte, n int)

//go:noescape
func decryptBlocksAVX2x16(rk *uint32, dst, src *byte, n int)

//go:noescape
func encryptBlocksAVX512x16(rk *uint32, dst, src *byte, n int)

//go:noescape
func decryptBlocksAVX512x16(rk *uint32, dst, src *byte, n int)

//go:noescape
func encryptBlocksAVX512x32(rk *uint32, dst, src *byte, n int)

//go:noescape
func decryptBlocksAVX512x32(rk *uint32, dst, src *byte, n int)

//go:noescape
func encryptBlocksAVX512x48(rk *uint32, dst, src *byte, n int)

//go:noescape
func decryptBlocksAVX512x48(rk *uint32, dst, src *byte, n int)

// hasAVX2 and hasAVX512F are generated by amd64.FeatureProbe: the processor
// reports the feature AND the operating system saves the vector state.
func hasAVX2() bool
func hasAVX512F() bool

// useAVX2 and useAVX512 gate the kernels; the tests clear them to reach the
// next path down (AVX-512, then AVX2, then pure Go).
var (
	useAVX2   = hasAVX2()
	useAVX512 = hasAVX512F()
)

// kernFn is the signature of every kernel above. kern holds them, so that the
// dispatch below is plain Go that the tests run against Go stand-ins on a
// processor that lacks the instructions: only the call itself, one line, needs
// the hardware.
type kernFn func(rk *uint32, dst, src *byte, n int)

type kernPair struct{ enc, dec kernFn }

func (p kernPair) pick(dec bool) kernFn {
	if dec {
		return p.dec
	}
	return p.enc
}

var kern = struct{ avx2x8, avx2x16, avx512x16, avx512x32, avx512x48 kernPair }{
	kernPair{encryptBlocksAVX2x8, decryptBlocksAVX2x8},
	kernPair{encryptBlocksAVX2x16, decryptBlocksAVX2x16},
	kernPair{encryptBlocksAVX512x16, decryptBlocksAVX512x16},
	kernPair{encryptBlocksAVX512x32, decryptBlocksAVX512x32},
	kernPair{encryptBlocksAVX512x48, decryptBlocksAVX512x48},
}

// At most maxBytes per kernel call: assembly without a frame cannot be
// preempted, so a huge buffer in one call would hold up the garbage
// collector's stop-the-world for its whole duration.
const maxBytes = 64 << 10

// bulkBlocks runs as many whole chunks of src as it can through the vector
// kernels (AVX-512 first, then AVX2 on what is left) and returns the number
// of bytes it did; the caller does the rest. dst must be at least as long as
// src, which is a multiple of 16.
func (c *serpentCipher) bulkBlocks(dst, src []byte, dec bool) int {
	done := 0
	rk := &c.rk[0]
	if useAVX512 {
		for len(src)-done >= 16*BlockSize {
			rest := min(len(src)-done, maxBytes)
			d, s := &dst[done], &src[done]
			switch {
			case rest >= 48*BlockSize:
				n := rest / (48 * BlockSize)
				kern.avx512x48.pick(dec)(rk, d, s, n)
				done += n * 48 * BlockSize
			case rest >= 32*BlockSize:
				kern.avx512x32.pick(dec)(rk, d, s, 1)
				done += 32 * BlockSize
			default:
				kern.avx512x16.pick(dec)(rk, d, s, 1)
				done += 16 * BlockSize
			}
		}
	}
	if useAVX2 {
		for len(src)-done >= 8*BlockSize {
			rest := min(len(src)-done, maxBytes)
			d, s := &dst[done], &src[done]
			if n := rest / (16 * BlockSize); n > 0 {
				kern.avx2x16.pick(dec)(rk, d, s, n)
				done += n * 16 * BlockSize
				continue
			}
			kern.avx2x8.pick(dec)(rk, d, s, 1)
			done += 8 * BlockSize
		}
	}
	return done
}
